26	    /// Creates a new Matcher with given options.
27	    ///
28	    /// Check [glob website](https://docs.rs/glob/latest/glob/struct.MatchOptions.html) for [MatchOptions]
29	    pub fn new(options: MatchOptions) -> Self {
30	        Self {
31	            root: None,
32	            git_ignore: None,
33	            patterns: Vec::new(),
34	            options,
35	            already_checked: RwLock::new(HashMap::default()),
36	        }
37	    }
38	
39	    pub fn empty() -> Self {
40	        Self {
41	            root: None,
42	            git_ignore: None,
43	            patterns: Vec::new(),
44	            options: MatchOptions::default(),
45	            already_checked: RwLock::new(HashMap::default()),
46	        }
47	    }
